class Solution {
public:

    struct Node {
        int node, rem, cst;
        Node(int node, int rem, int cst) {
            this->node = node;
            this->rem = rem;
            this->cst = cst;
        }
    };

    struct Comparator {
        bool operator()(const Node &a, const Node &b) {
            return -a.cst < -b.cst;
        }
    };

    int minimumCost(int n, vector<vector<int>>& highways, int discounts) {
        vector<vector<pair<int, int>>> adj;
        adj.resize(n);
        for (auto highway : highways) {
            adj[highway[0]].push_back({highway[1], highway[2]});
            adj[highway[1]].push_back({highway[0], highway[2]});
        }
        priority_queue<Node, vector<Node>, Comparator> pq;
        pq.push(Node(0, discounts, 0));
        vector<vector<int>> cost(n, vector<int>(discounts + 1, INT_MAX));
        cost[0][discounts] = 0;

        while (!pq.empty()) {
            Node cur = pq.top();
            pq.pop();
            int node = cur.node;
            int rem = cur.rem;
            int cst = cur.cst;

            if (node == (n-1)) {
                return cst;
            }
            for (auto v : adj[node]) {
                int adjn = v.first;
                int adjc = v.second;
                if ((cst + adjc) < cost[adjn][rem]) {
                    cost[adjn][rem] = cst + adjc;
                    pq.push(Node(adjn, rem, cst + adjc));
                }
                if (rem > 0 && (cst + adjc/2) < cost[adjn][rem-1]) {
                    cost[adjn][rem-1] = cst + adjc/2;
                    pq.push(Node(adjn, rem - 1, cst + adjc/2));
                }
            }
        }
        return -1;
    }
};

class Solution:
    def minimumCost(self, n: int, highways: List[List[int]], discounts: int) -> int:
        g = defaultdict(list)
        for a, b, c in highways:
            g[a].append((b, c))
            g[b].append((a, c))
        q = [(0, 0, 0)]
        dist = [[inf] * (discounts + 1) for _ in range(n)]
        while q:
            cost, i, k = heappop(q)
            if k > discounts:
                continue
            if i == n - 1:
                return cost
            if dist[i][k] > cost:
                dist[i][k] = cost
                for j, v in g[i]:
                    heappush(q, (cost + v, j, k))
                    heappush(q, (cost + v // 2, j, k + 1))
        return -1

class Solution {
    public int minimumCost(int n, int[][] highways, int discounts) {
        List<int[]>[] g = new List[n];
        for (int i = 0; i < n; ++i) {
            g[i] = new ArrayList<>();
        }
        for (var e : highways) {
            int a = e[0], b = e[1], c = e[2];
            g[a].add(new int[] {b, c});
            g[b].add(new int[] {a, c});
        }
        PriorityQueue<int[]> q = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        q.offer(new int[] {0, 0, 0});
        int[][] dist = new int[n][discounts + 1];
        for (var e : dist) {
            Arrays.fill(e, Integer.MAX_VALUE);
        }
        while (!q.isEmpty()) {
            var p = q.poll();
            int cost = p[0], i = p[1], k = p[2];
            if (k > discounts || dist[i][k] <= cost) {
                continue;
            }
            if (i == n - 1) {
                return cost;
            }
            dist[i][k] = cost;
            for (int[] nxt : g[i]) {
                int j = nxt[0], v = nxt[1];
                q.offer(new int[] {cost + v, j, k});
                q.offer(new int[] {cost + v / 2, j, k + 1});
            }
        }
        return -1;
    }
}

